  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rats, (+)-bicuculline penetrated the brain in a dose-dependent manner measured by LC-MS/MS; this closest analogue shares the phthalide-isoquinoline scaffold with the query, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Schisandrin B showed a logPSFu,brain of -3.2 and reached 0.327 µg/g in mouse brain, indicating efficient brain equilibration in a related polycyclic aromatic ether.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine brain concentrations were almost equal to plasma concentrations in rats, demonstrating robust BBB crossing in a related aporphine alkaloid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "α-Allocryptopine was detected in rat CSF after administration, providing direct evidence that related benzylisoquinoline alkaloids cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Corydaline was detected in rat CSF and reached brain levels close to other tissues after oral dosing, supporting effective BBB penetration in a structurally related alkaloid.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is noscapine, a phthalide-isoquinoline alkaloid with favorable passive BBB properties. The closest analogue bicuculline and multiple related alkaloids show direct brain or CSF penetration in rodents, with no contradictory evidence. Therefore, meaningful CNS access is predicted.",
